// Input JSON (considerando que você já tem o objeto como input)
const inputData = $json;

// Resultados do "items"
const items = inputData.items;

// Resultado da próxima página (nextPage)
const nextPage = inputData.queries.nextPage[0];

// Criação do array para armazenar os resultados
const results = items.map((item, index) => {
    const firstName = item.pagemap.metatags ? item.pagemap.metatags[0]["profile:first_name"] : '';
    const lastName = item.pagemap.metatags ? item.pagemap.metatags[0]["profile:last_name"] : '';
    const sobre = item.pagemap.metatags ? item.pagemap.metatags[0]["og:description"] : '';  // Novo campo 'sobre'

    return {
        nome: `${firstName} ${lastName}`,
        titulo: item.title,
        link: item.link,
        sobre: sobre,  // Colocando 'sobre' logo após 'link'
        imagem: item.pagemap.cse_thumbnail ? item.pagemap.cse_thumbnail[0].src : '',
        novaPesquisa: nextPage ? nextPage.startIndex : null,
        temMaisResultados: nextPage.startIndex < 100 ? true : false
    };
});

// Retorne os resultados
return results;

