// Get all input items
const inputItems = $input.all();
console.log("Input items count:", inputItems.length);

// Extract pagination values with correct field names
let novaPesquisa = 1;
let temMaisResultados = false;

if (inputItems && inputItems.length > 0) {
	const firstItem = inputItems[0];

	if (firstItem.json) {
		console.log("First item JSON:", JSON.stringify(firstItem.json));

		// Look for "novaPesquisa" instead of "startIndex"
		if (firstItem.json.novaPesquisa !== undefined) {
			novaPesquisa = firstItem.json.novaPesquisa;
		}

		// Look for "temMaisResultados" instead of "hasMoreResults"
		if (firstItem.json.temMaisResultados !== undefined) {
			temMaisResultados = firstItem.json.temMaisResultados;
			console.log("Found temMaisResultados:", temMaisResultados);
		}
	}
}

// Return pagination control info
return {
	json: {
		continueLoop: temMaisResultados,
		novaPesquisa: novaPesquisa,
	},
};

